formData.yamlProperties:
useBrick:
  - brick: style
    properties:
      textContent: |
            .card-header {
              display: flex;
              justify-content: space-between;
              align-items: center;
            }

            .card-label {
              font-size: 15px;
              font-weight: 600;
              color: #333;
              margin: 0;
            }

            .card-value {
              font-size: 28px;
              font-weight: 700;
              color: #1c1c1c;
              display: flex;
              align-items: center;
              gap: 8px;
            }

            .card-status-dot {
              width: 10px;
              height: 10px;
              border-radius: 50%;
              display: inline-block;
            }

            .card-meta {
              color: #666;
              font-size: 14px;
            }

            .card-meta {
              color: #888;
            }

            .card-status-dot--normal {
              background-color: var(--theme-green-color); /* 绿色 正常 */
            }

            .card-status-dot--warning {
              background-color: var(--theme-orange-color); /* 黄色 警告 */
            }

            .card-status-dot--error {
              background-color: var(--theme-red-color); /* 红色 错误 */
            }

  - brick: div
    properties:
      classList: [ card-header ]
    slots:
      items:
        bricks:
          - brick: div
            properties:
              classList: [ card-label ]
              textContent: 交换机Ping状态
          - brick: presentational-bricks.basic-icon
            properties:
              bg: |
                <%
                  _.cond([
                      [t => t < 0, _.constant("var(--theme-red-background)")],
                      [t => t >= 0 && t < 50, _.constant("var(--theme-green-background)")],
                      [t => t >= 50 && t < 150, _.constant("var(--theme-orange-background)")],
                      [_.stubTrue, _.constant("var(--theme-red-background)")]
                  ])(_.get(_.maxBy(CTX.DS.ping, 'time'), 'ping', -1))
                %>
              bgBorderRadius: 15px
              bgSize: 45px
              icon:
                lib: antd
                icon: |
                  <%
                  _.cond([
                      [t => t < 0, _.constant("close-circle")],
                      [t => t < 150, _.constant("check-circle")],
                      [_.stubTrue, _.constant("close-circle")]
                  ])(_.get(_.maxBy(CTX.DS.ping, 'time'), 'ping', -1))
                  %>
                theme: outlined
                color: |
                  <%
                  _.cond([
                      [t => t < 0, _.constant("var(--theme-red-color)")],
                      [t => 0 <= t < 50, _.constant("var(--theme-green-color)")],
                      [t => t < 150, _.constant("var(--theme-orange-color)")],
                      [_.stubTrue, _.constant("var(--theme-red-color)")]
                  ])(_.get(_.maxBy(CTX.DS.ping, 'time'), 'ping', -1))
                  %>
              renderBg: true
              size: 24px

  - brick: div
    properties: 
      classList: [ card-value ]
    slots:
      items:
        bricks:
          - brick: span
            properties:
              classList: 
                - <% `card-status-dot card-status-dot--${_.cond([[t=>t<0,_.constant("error")],[t=>t>=0&&t<50,_.constant("normal")],[t=>t>=50&&t<150,_.constant("warning")],[_.stubTrue,_.constant("error")]])(_.get(_.maxBy(CTX.DS.ping, 'time'), 'ping', -1))}` %>

          - brick: span
            properties: 
              textContent: <% _.round(_.get(_.maxBy(CTX.DS.ping, 'time'), 'ping', -1), 2) %>
          - brick: span
            properties: 
              textContent: ms
  - brick: div
    properties:
      textContent: |
        <% `上次检查：${moment.unix(_.maxBy(_.filter(CTX.DS.ping, o=>o.time), 'time').time).format("YYYY-MM-DD HH:mm")}` %>
      classList: [ card-meta ]

